(function(g){'use strict';
 function elapsed(start,now=Date.now()){const time=typeof start==='string'&&start?Date.parse(start):NaN;return Number.isFinite(time)&&Number.isFinite(now)?Math.max(0,Math.floor((now-time)/1000)):0;}
 function duration(seconds){seconds=Math.max(0,Math.floor(Number(seconds)||0));return[Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':');}
 function businessDay(now=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);}
 function previousDay(today=businessDay()){const d=new Date(today+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-1);return d.toISOString().slice(0,10);}
 function lastWorked(rows=[],today=businessDay()){for(const shift of [...rows].filter(s=>{const day=s.work_date||s.workDate;return typeof day==='string'&&/^\d{4}-\d\d-\d\d$/.test(day)&&day<today&&Number.isFinite(Date.parse(s.ended_at||s.endedAt));}).sort((a,b)=>(b.work_date||b.workDate).localeCompare(a.work_date||a.workDate)||Date.parse(b.ended_at||b.endedAt)-Date.parse(a.ended_at||a.endedAt))){const segments=(shift.segments||[]).filter(s=>(s.type||s.segment_type)==='job'&&(s.jobId||s.job_id)&&Number.isFinite(Date.parse(s.startedAt||s.started_at))).sort((a,b)=>Date.parse(b.startedAt||b.started_at)-Date.parse(a.startedAt||a.started_at));if(segments.length)return{jobId:segments[0].jobId||segments[0].job_id,shiftId:shift.id,date:shift.work_date||shift.workDate};}return null;}

 function angle(start,now=Date.now()){return elapsed(start,now)%3600/10;}
 function update(immediate=false){if(!g.document)return;for(const n of document.querySelectorAll('[data-confirmed-start]')){const text=duration(elapsed(n.dataset.confirmedStart));if(n.textContent!==text)n.textContent=text;if(n.classList.contains('field-elapsed')){n.style.removeProperty('font-size');const range=document.createRange();range.selectNodeContents(n);const width=range.getBoundingClientRect().width,available=n.clientWidth,base=parseFloat(getComputedStyle(n).fontSize),minimum=parseFloat(getComputedStyle(document.body).fontSize);if(available&&width>available)n.style.setProperty('font-size',Math.max(minimum,Math.floor(base*(available-4)/width))+'px','important');}}for(const dial of document.querySelectorAll('[data-field-dial-start]')){const hand=dial.querySelector('[data-field-clock-hand]');if(!hand)continue;const seconds=elapsed(dial.dataset.fieldDialStart),degrees=seconds/10;if(immediate){hand.style.setProperty('transition','none','important');requestAnimationFrame(()=>requestAnimationFrame(()=>hand.style.removeProperty('transition')));}hand.dataset.angle=String(degrees%360);hand.style.transform='rotate('+degrees+'deg)';}}
 function measure(){if(!g.document||document.body.dataset.fieldShell!=='true')return;const nav=document.querySelector('#portal-navigation'),main=document.querySelector('#portal-main');if(!nav||!main)return;const bounds=nav.getBoundingClientRect(),style=getComputedStyle(main),space=Math.max(180,bounds.top-main.getBoundingClientRect().top-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom)-8);document.documentElement.style.setProperty('--field-available-height',space+'px');document.body.dataset.fieldDense=space<420||Math.max(parseFloat(getComputedStyle(document.documentElement).fontSize),parseFloat(getComputedStyle(document.body).fontSize))>22?'true':'false';document.documentElement.style.setProperty('--field-nav-height',bounds.height+'px');const home=document.querySelector('.field-home-list');if(home&&!home.dataset.spaceMeasured){document.body.dataset.fieldHomeCompact='false';document.body.dataset.fieldHomeCompact=home.getBoundingClientRect().height>space+2?'true':'false';home.dataset.spaceMeasured='true';}const card=document.querySelector('.field-punch-dial-page .field-punch-clock'),dial=card?.querySelector('.field-clock-dial');if(dial){const context=card.querySelector('.field-punch-context'),action=card.querySelector('.field-round-action'),extra=[...card.children].filter(n=>n!==context&&n!==action&&n!==dial).reduce((sum,n)=>sum+n.getBoundingClientRect().height+8,0),landscape=innerHeight<490;const room=landscape?card.clientHeight-16-extra:card.clientHeight-context.getBoundingClientRect().height-action.getBoundingClientRect().height-extra-16-16+32;const size=Math.max(96,Math.min(280,landscape?room:Math.min(room,innerWidth*.74),card.clientWidth-28));dial.style.setProperty('--field-dial-size',Math.floor(size)+'px');}update();g.dispatchEvent(new CustomEvent('mir:field-space',{detail:{height:space}}));}
 const api={elapsed,duration,businessDay,previousDay,lastWorked,angle,update,measure};if(typeof module==='object'&&module.exports)module.exports=api;else{g.MIRFieldRuntime=Object.freeze(api);setInterval(update,1000);g.addEventListener('pageshow',()=>{update(true);measure();});g.addEventListener('resize',measure);document.addEventListener('visibilitychange',()=>{update(true);measure();});g.visualViewport?.addEventListener('resize',measure);new MutationObserver(measure).observe(document.documentElement,{attributes:true,attributeFilter:['data-mir-theme','data-mir-text']});}
})(globalThis);
